package com.muhammetgecgil.mg3dscanner;

import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.graphics.*;import android.net.*;import android.provider.*;import android.view.*;import android.widget.*;import java.util.*;

public class HomeActivity extends Activity{
 private ContentObserver observer; private boolean watching=false; private long watchStart=0;
 private TextView txt(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);v.setPadding(22,16,22,16);return v;}
 private Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(18);b.setMinHeight(72);return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(12,13,16));ScrollView sv=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(24,32,24,32);r.setBackgroundColor(Color.rgb(12,13,16));sv.addView(r);TextView t=txt("MG 3D STUDIO PRO",30);t.setGravity(Gravity.CENTER);r.addView(t);TextView s=txt("Mobil fotogrametri • continuous surface • PRO CAD inceleme",15);s.setTextColor(Color.LTGRAY);s.setGravity(Gravity.CENTER);r.addView(s);Space sp=new Space(this);r.addView(sp,new LinearLayout.LayoutParams(1,24));Button scan=btn("📷 PRO 3D TARA / MODEL ÜRET");scan.setOnClickListener(v->{startWatch();startActivity(new Intent(this,MainActivity.class));});r.addView(scan);Button view=btn("🧊 PRO CAD / 3D DOSYA AÇ");view.setOnClickListener(v->startActivity(new Intent(this,ProCadViewerActivity.class)));r.addView(view);TextView f=txt("TELEFONA GÖRE PRO ARAÇLAR\n\n• Surface / wireframe\n• Perspektif / ortografik projeksiyon\n• Ön / Sağ / Üst / İzometrik görünüş\n• X / Y / Z canlı kesit düzlemi\n• Kesit slider'ı\n• Model üzerinden mesafe ölçümü\n• 3 noktalı açı ölçümü\n• X/Y/Z bounding ölçüleri\n• 360° orbit + pinch zoom\n• OBJ • STL • PLY • XYZ • GLB • STEP/STP • IGES/IGS\n\nTarama bitince yeni model otomatik PRO CAD Viewer'da açılır.",14);f.setTextColor(Color.LTGRAY);r.addView(f);setContentView(sv);}
 private void startWatch(){stopWatch();watching=true;watchStart=System.currentTimeMillis();observer=new ContentObserver(new Handler(Looper.getMainLooper())){@Override public void onChange(boolean self,Uri uri){super.onChange(self,uri);if(!watching)return;checkUri(uri);}};getContentResolver().registerContentObserver(MediaStore.Downloads.EXTERNAL_CONTENT_URI,true,observer);}
 private void checkUri(Uri uri){try{Uri target=uri;if(target==null||target.toString().equals(MediaStore.Downloads.EXTERNAL_CONTENT_URI.toString()))target=findLatest();if(target==null)return;String[]p={MediaStore.Downloads.DISPLAY_NAME,MediaStore.Downloads.RELATIVE_PATH,MediaStore.Downloads.DATE_ADDED};try(Cursor c=getContentResolver().query(target,p,null,null,null)){if(c==null||!c.moveToFirst())return;String n=c.getString(0),path=c.getString(1);long sec=c.getLong(2);if(n==null)return;String low=n.toLowerCase(Locale.US);boolean ours=n.startsWith("MG3D_")&&(low.endsWith(".glb")||low.endsWith(".obj"));boolean folder=path==null||path.contains("MG3DScanner");boolean recent=sec<=0||sec*1000L>=watchStart-5000;if(ours&&folder&&recent){watching=false;stopWatch();Intent i=new Intent(this,ProCadViewerActivity.class);i.setData(target);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}}}catch(Exception ignored){}}
 private Uri findLatest(){String[]p={MediaStore.Downloads._ID,MediaStore.Downloads.DISPLAY_NAME};String sel=MediaStore.Downloads.DISPLAY_NAME+" LIKE ?";String[]a={"MG3D_%.glb"};try(Cursor c=getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,p,sel,a,MediaStore.Downloads.DATE_ADDED+" DESC")){if(c!=null&&c.moveToFirst())return ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,c.getLong(0));}catch(Exception ignored){}return null;}
 private void stopWatch(){if(observer!=null){try{getContentResolver().unregisterContentObserver(observer);}catch(Exception ignored){}observer=null;}}
 @Override protected void onDestroy(){stopWatch();super.onDestroy();}
}
